/** Canonical shells and completed payload caches have independent publication and retention contracts. */
class LmdbCanonicalValueCacheTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:canonical:subject");
	private static final IRI PREDICATE = VF.createIRI("urn:canonical:predicate");
	private static final IRI DATATYPE = VF.createIRI("urn:canonical:datatype");
	private final ConcurrentCleaner cleaner = new ConcurrentCleaner();

	@TempDir
	Path directory;
	private CountingValueStore store;

	@BeforeEach
	void openStore() throws IOException {
		store = new CountingValueStore(directory.resolve("values"), 32);
	}

	@AfterEach
	void closeStore() throws IOException {
		store.close();
	}

	@ParameterizedTest
	@EnumSource(Shape.class)
	void sameAssociationSharesUnresolvedModels(Shape shape) throws Exception {
		Value expected = shape.value();
		long id = commitValue(expected);
		LmdbValue first = store.getLazyValue(id);
		LmdbValue second = store.getLazyValue(id);
		assertSame(first, second, "Repeated lookups must share the unresolved model of this association");
		assertTrue(first.getValueStoreRevision() instanceof ValueStoreRevision.Lazy);
		first.init();
		assertEquals(expected, first);
		assertSame(first, store.getLazyValue(id), "Completion must preserve canonical identity");
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void simultaneousLookupsDecodeOnceAndEscapeShutdown(boolean nested) throws Exception {
		Value expected = nested ? Shape.NESTED.value() : Shape.IRI.value();
		long id = commitValue(expected);
		store.countedId = id;
		ExecutorService executor = Executors.newFixedThreadPool(4);
		CountDownLatch lookupsReady = new CountDownLatch(4);
		CountDownLatch releaseInitialization = new CountDownLatch(1);
		List<Future<LmdbValue>> results = new ArrayList<>();
		try {
			for (int i = 0; i < 4; i++) {
				results.add(executor.submit(() -> {
					LmdbValue value = store.getLazyValue(id);
					lookupsReady.countDown();
					assertTrue(releaseInitialization.await(10, TimeUnit.SECONDS));
					value.init();
					return value;
				}));
			}
			assertTrue(lookupsReady.await(10, TimeUnit.SECONDS), "All cold lookups must precede initialization");
			releaseInitialization.countDown();
			LmdbValue first = results.getFirst().get(10, TimeUnit.SECONDS);
			for (Future<LmdbValue> result : results) {
				assertSame(first, result.get(10, TimeUnit.SECONDS),
						"Concurrent same-association lookups share one shell");
			}
			assertEquals(1, store.resolutions.get(), "One canonical model initializes this association once");
			store.close();
			assertEquals(expected, executor.submit(() -> {
				// RDF triple-term rendering differs across ValueFactory implementations; compare RDF meaning and hash.
				assertNotNull(first.stringValue());
				assertEquals(expected, first);
				assertEquals(expected.hashCode(), first.hashCode());
				return first;
			}).get(10, TimeUnit.SECONDS));
		} finally {
			releaseInitialization.countDown();
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(10, TimeUnit.SECONDS));
		}
	}

	@ParameterizedTest
	@EnumSource(Shape.class)
	void consecutiveSameTypeIdsUseConfiguredCacheCapacity(Shape shape) throws Exception {
		store.close();
		store = new CountingValueStore(directory.resolve("capacity-values"), 128);
		store.startTransaction(true);
		long[] ids = new long[16];
		for (int i = 0; i < ids.length; i++) {
			ids[i] = store.storeValue(shape.distinctValue(i));
		}
		store.commit();
		assertTrue(ValueIds.getValue(ids[ids.length - 1]) - ValueIds.getValue(ids[0]) < 128,
				"The fixture's logical IDs must fit within its configured capacity");
		LmdbValue[] values = new LmdbValue[ids.length];
		for (int i = 0; i < ids.length; i++) {
			values[i] = store.getLazyValue(ids[i]);
		}
		for (int i = 0; i < ids.length; i++) {
			assertSame(values[i], store.getLazyValue(ids[i]),
					"Encoded type tags must not collapse consecutive same-type IDs into one cache slot");
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 1, 3, 5, 31 })
	void inlineAndSmallCachesPreserveMeaningAcrossCollisions(int capacity) throws Exception {
		store.close();
		store = new CountingValueStore(directory.resolve("small-values"), capacity, true);
		Value[] expected = { SUBJECT, VF.createLiteral(42), VF.createLiteral(0.125d), VF.createLiteral("xy"),
				Shape.NESTED.value() };
		store.startTransaction(true);
		long[] ids = new long[expected.length];
		for (int i = 0; i < expected.length; i++) {
			ids[i] = store.storeValue(expected[i]);
		}
		store.commit();
		for (int i = 1; i <= 3; i++) {
			assertTrue(ValueIds.isInlined(ids[i]), "The fixture must exercise actual inlined ID representations");
		}
		LmdbValue[] escaped = new LmdbValue[ids.length];
		for (int i = 0; i < ids.length; i++) {
			escaped[i] = store.getLazyValue(ids[i]);
			assertSame(escaped[i], store.getLazyValue(ids[i]));
		}
		for (int i = 0; i < ids.length; i++) {
			assertEquals(expected[i], store.getValue(ids[i]), "Completed reads preserve every colliding association");
			assertEquals(expected[i], store.getLazyValue(ids[i]));
		}
		store.close();
		for (int i = 0; i < ids.length; i++) {
			assertEquals(expected[i], escaped[i], "Eviction and shutdown preserve escaped inlined and nested values");
		}
	}

	@Test
	void completedReadsNeverConsumeUnresolvedCanonicalEntries() throws Exception {
		Value expected = Shape.NESTED.value();
		long id = commitValue(expected);
		store.countedId = id;
		LmdbValue unresolved = store.getLazyValue(id);
		assertNull(store.cachedValue(id), "Native payload copying must not observe an unresolved shell");
		LmdbValue completed = store.getValue(id);
		assertNotSame(unresolved, completed, "The native read must construct a completed payload independently");
		assertEquals(0, store.resolutions.get(),
				"A completed native read must not wait on the unresolved model monitor");
		assertEquals(expected, completed);
		unresolved.init();
		assertEquals(1, store.resolutions.get());
		assertEquals(expected, unresolved);
		assertSame(unresolved, store.getLazyValue(id));
	}

	@Test
	void boundedCollisionsPreserveEscapedMeanings() throws Exception {
		store.close();
		store = new CountingValueStore(directory.resolve("colliding-values"), 1);
		Value firstExpected = Shape.NESTED.value();
		Value secondExpected = VF.createIRI("urn:canonical:other");
		Value thirdExpected = VF.createBNode("canonical-other-node");
		store.startTransaction(true);
		long firstId = store.storeValue(firstExpected);
		long secondId = store.storeValue(secondExpected);
		long thirdId = store.storeValue(thirdExpected);
		store.commit();
		LmdbValue first = store.getLazyValue(firstId);
		LmdbValue second = store.getLazyValue(secondId);
		LmdbValue third = store.getLazyValue(thirdId);
		assertNotSame(first, second);
		assertNotSame(second, third);
		LmdbValue replacementFirst = store.getLazyValue(firstId);
		assertNotSame(first, replacementFirst, "A one-slot collision must release the previous cache owner");
		store.close();
		assertEquals(firstExpected, first);
		assertEquals(firstExpected, replacementFirst);
		assertEquals(secondExpected, second);
		assertEquals(thirdExpected, third);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void abortedCanonicalShellCannotDecodeLaterReuse(boolean nested) throws Exception {
		Value expected = nested ? Shape.NESTED.value() : Shape.IRI.value();
		store.startTransaction(true);
		long id = store.storeValue(expected);
		LmdbValue aborted = store.getLazyValue(id);
		assertSame(aborted, store.getLazyValue(id));
		store.rollback();
		assertThrows(SailException.class, aborted::init);
		// The running allocator retains its append high-water mark; reopen exercises actual reassignment of
		// rolled-back appended IDs from the committed dictionary rather than assuming immediate in-process reuse.
		store.close();
		store = new CountingValueStore(directory.resolve("values"), 32);
		Value replacement = nested
				? VF.createTripleTerm(SUBJECT, PREDICATE,
						VF.createTripleTerm(SUBJECT, PREDICATE, VF.createLiteral("replacement", DATATYPE)))
				: VF.createIRI("urn:canonical:replacement");
		long replacementId = commitValue(replacement);
		assertEquals(id, replacementId, "The actual aborted append must be reassigned");
		LmdbValue newValue = store.getLazyValue(replacementId);
		assertNotSame(aborted, newValue);
		assertEquals(replacement, newValue);
		assertThrows(SailException.class, aborted::init, "Later ID reuse must not revive the aborted association");
	}

	@Test
	void retirementReleasesCacheOwnedLazyEpoch() throws Exception {
		Value expected = Shape.IRI.value();
		long id = commitValue(expected);
		CountDownLatch collected = registerUnescapedLazy(id);
		retire(Set.of(id));
		awaitCollection(collected);
	}

	@Test
	void lateCompletedNestedParentCannotRetainRetiredChildren() throws Exception {
		CountDownLatch collected = completeAndRetireNestedParent();
		awaitCollection(collected);
	}

	@Test
	void strictNativeSnapshotsKeepIndependentLazyOwnership() throws Exception {
		Value expected = Shape.NESTED.value();
		long id = commitValue(expected);
		try (ValueStore.ReadSnapshotReservation firstReservation = store.reserveReadSnapshot();
				ValueStore.ReadSnapshot firstSnapshot = firstReservation.start();
				ValueStore.ReadSnapshotReservation secondReservation = store.reserveReadSnapshot();
				ValueStore.ReadSnapshot secondSnapshot = secondReservation.start()) {
			LmdbValue first = store.getLazyValue(firstSnapshot, id);
			LmdbValue second = store.getLazyValue(secondSnapshot, id);
			assertNotSame(first, second);
			assertNotSame(first.getValueStoreRevision(), second.getValueStoreRevision());
			assertEquals(expected, first);
			assertEquals(expected, second);
		}
	}

	private long commitValue(Value value) throws IOException {
		store.startTransaction(true);
		long id = store.storeValue(value);
		store.commit();
		return id;
	}

	private void retire(Set<Long> ids) throws IOException {
		store.startTransaction(true);
		Set<Long> pending = ids;
		while (!pending.isEmpty()) {
			Set<Long> next = new HashSet<>();
			store.gcIds(pending, next);
			pending = next;
		}
		store.commit();
	}

	private CountDownLatch registerUnescapedLazy(long id) throws IOException {
		LmdbValue value = store.getLazyValue(id);
		CountDownLatch collected = trackCollection(value.getValueStoreRevision());
		Reference.reachabilityFence(value);
		return collected;
	}

	private CountDownLatch completeAndRetireNestedParent() throws Exception {
		long id = commitValue(Shape.NESTED.value());
		LmdbValue parent = store.getLazyValue(id);
		ValueStoreRevision original = parent.getValueStoreRevision();
		CountDownLatch collected = trackCollection(original);
		parent.init();
		ValueStoreRevision source = parent.getValueStoreRevision();
		retire(Set.of(id));
		// A delayed completion callback may arrive after clearCaches even though its payload was completed earlier.
		// Its children still retain their captured Lazy epoch; obsolete source storage must not retain that epoch.
		source.valueInitialized(id, parent);
		Reference.reachabilityFence(original);
		Reference.reachabilityFence(parent);
		return collected;
	}

	private CountDownLatch trackCollection(Object referent) {
		CountDownLatch collected = new CountDownLatch(1);
		cleaner.register(referent, collected::countDown);
		return collected;
	}

	private void awaitCollection(CountDownLatch collected) throws InterruptedException {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (collected.getCount() != 0 && System.nanoTime() < deadline) {
			System.gc();
			collected.await(100, TimeUnit.MILLISECONDS);
		}
		assertEquals(0, collected.getCount(), "Retired cache storage must release unreachable Lazy capabilities");
	}

	private static final class CountingValueStore extends ValueStore {
		private volatile long countedId = LmdbValue.UNKNOWN_ID;
		private final AtomicInteger resolutions = new AtomicInteger();

		private CountingValueStore(Path path, int cacheSize) throws IOException {
			this(path, cacheSize, false);
		}

		private CountingValueStore(Path path, int cacheSize, boolean inline) throws IOException {
			super(path.toFile(), new LmdbStoreConfig().setValueCacheSize(cacheSize).setInlineLiterals(inline));
		}

		@Override
		boolean resolveValue(long id, LmdbValue value, ValueStoreRevision revision) {
			if (id == countedId) {
				resolutions.incrementAndGet();
			}
			return super.resolveValue(id, value, revision);
		}
	}

	private enum Shape {
		IRI,
		LITERAL,
		BNODE,
		TRIPLE,
		NESTED;

		private Value value() {
			return switch (this) {
			case IRI -> SUBJECT;
			case LITERAL -> VF.createLiteral("canonical literal", DATATYPE);
			case BNODE -> VF.createBNode("canonical-node");
			case TRIPLE -> VF.createTripleTerm(SUBJECT, PREDICATE, VF.createLiteral("triple literal", DATATYPE));
			case NESTED -> VF.createTripleTerm(SUBJECT, PREDICATE,
					VF.createTripleTerm(SUBJECT, PREDICATE, VF.createLiteral("nested literal", DATATYPE)));
			};
		}

		private Value distinctValue(int index) {
			return switch (this) {
			case IRI -> VF.createIRI("urn:canonical:capacity:" + index);
			case LITERAL -> VF.createLiteral("capacity literal " + index, DATATYPE);
			case BNODE -> VF.createBNode("capacity-node-" + index);
			case TRIPLE -> VF.createTripleTerm(SUBJECT, PREDICATE,
					VF.createLiteral("capacity triple " + index, DATATYPE));
			case NESTED -> VF.createTripleTerm(SUBJECT, PREDICATE,
					VF.createTripleTerm(SUBJECT, PREDICATE, VF.createLiteral("capacity nested " + index, DATATYPE)));
			};
		}
	}
}
